class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = defaultdict(list)

    def shortest_path(self, start, end):
        if start not in self.nodes or end not in self.nodes:
            raise KeyError("Node not in graph")

        if start == end:
            return (0, [start])

        queue = [(0, [start])]
        visited = set()

        while queue:
            (cost, path) = heapq.heappop(queue)

            if path[-1] not in visited:
                visited.add(path[-1])

                if path[-1] == end:
                    return (cost, path)

                for (next_node, weight) in self.edges[path[-1]]:
                    if next_node not in visited:
                        heapq.heappush(queue, (cost + weight, path + [next_node]))

        return None

